def start_session(
    self,
    resource_id: str,
    total: int,
    digest: str,
    registered_digest: str,
) -> tuple[bool, SessionStatus]:
    """Open an upload session explicitly, before any chunk bytes arrive.

    ``total`` is a positive integer and ``digest`` the lowercase
    64-character hex target digest, both already validated by the caller;
    ``registered_digest`` is the resource's registered digest.

    Returns ``(created, status)`` where ``created`` is ``True`` when a new
    session was opened (HTTP 201) and ``False`` when the same declaration
    was repeated (HTTP 200, idempotent; received chunks are kept). Raises
    :class:`ContentError` with ``content_already_complete`` after assembly,
    ``digest_conflict`` when the declared digest differs from the
    registered one (no session is created), or ``chunk_conflict`` when an
    existing session was opened with a different total or digest.
    """

    session = self._sessions.get(resource_id)
    if session is not None and session.complete:
        raise ContentError(
            "content_already_complete",
            "Content for this resource is already complete.",
        )
    if digest != registered_digest:
        raise ContentError(
            "digest_conflict",
            "Target digest does not match the registered resource digest.",
        )
    if session is None:
        session = _Session(total=total, digest=digest)
        self._sessions[resource_id] = session
        return True, self._status_of(session)
    if session.total != total or session.digest != digest:
        raise ContentError(
            "chunk_conflict",
            "Start declaration conflicts with the existing upload session.",
        )
    return False, self._status_of(session)
